pub fn greater_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Problem statement guarantees equal lengths.
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x >= y)
        .collect()
}

